-- 4Peace one-time Supabase setup.
-- Additive only: no tables are dropped and imported rows never overwrite existing rows.
-- Demo seed rows and the superseded Nov 3 dump are excluded.
-- Development/staging only for now: legacy migrations disable RLS on several app tables.

-- ===== 001_initial_schema.sql =====

-- ============================================================
-- 4Peace Admin Dashboard — Supabase (PostgreSQL) Schema
-- Run this in your Supabase project → SQL Editor
-- ============================================================

-- ------------------------------------------------------------
-- Admins (Normal username + password authentication)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS admins (
  id            SERIAL PRIMARY KEY,
  username      VARCHAR(50) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL DEFAULT '4peace2026',
  full_name     VARCHAR(100) NOT NULL,
  email         VARCHAR(150),
  phone         VARCHAR(20),
  role          VARCHAR(30) DEFAULT 'Administrator',
  last_login    TIMESTAMPTZ,
  created_at    TIMESTAMPTZ DEFAULT NOW()
);

-- Default admin credentials:
-- Username: admin
-- Password: 4peace2026

-- ------------------------------------------------------------
-- Slots
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS slots (
  id           SERIAL PRIMARY KEY,
  slot_code    VARCHAR(10) NOT NULL UNIQUE,
  product_name VARCHAR(100) NOT NULL,
  stock        INT NOT NULL DEFAULT 0,
  capacity     INT NOT NULL DEFAULT 30,
  updated_at   TIMESTAMPTZ DEFAULT NOW()
);


-- ------------------------------------------------------------
-- Transactions
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS transactions (
  id         SERIAL PRIMARY KEY,
  ref_code   VARCHAR(30) NOT NULL,
  method     TEXT NOT NULL CHECK (method IN ('gcash','coin')),
  slot_id    INT REFERENCES slots(id) ON DELETE CASCADE,
  amount     NUMERIC(6,2) NOT NULL DEFAULT 10.00,
  created_at TIMESTAMPTZ DEFAULT NOW()
);


-- ------------------------------------------------------------
-- Device health
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS device_health (
  id                       SERIAL PRIMARY KEY,
  esp32_uptime_seconds     INT DEFAULT 0,
  coin_pulses_session      INT DEFAULT 0,
  sim800l_signal_pct       INT DEFAULT 0,
  buck1_voltage            NUMERIC(4,2) DEFAULT 0.00,
  buck2_voltage            NUMERIC(4,2) DEFAULT 0.00,
  tamper_status            TEXT DEFAULT 'idle' CHECK (tamper_status IN ('idle','triggered')),
  coin_box_pulses_total    INT DEFAULT 0,
  coin_box_capacity_pulses INT DEFAULT 1000,
  last_sync                TIMESTAMPTZ DEFAULT NOW()
);


-- ------------------------------------------------------------
-- Machine health logs
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS machine_health_logs (
  id         SERIAL PRIMARY KEY,
  level      TEXT NOT NULL DEFAULT 'info' CHECK (level IN ('info','warning','critical')),
  message    VARCHAR(255) NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);


-- ------------------------------------------------------------
-- Machine settings
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS machine_settings (
  id                    SERIAL PRIMARY KEY,
  unit_price            NUMERIC(6,2) NOT NULL DEFAULT 10.00,
  low_stock_threshold   INT NOT NULL DEFAULT 5,
  coin_box_alert_pct    INT NOT NULL DEFAULT 80,
  admin_sms_number      VARCHAR(20),
  tamper_alarm_enabled  BOOLEAN NOT NULL DEFAULT TRUE,
  auto_reset_coin_count BOOLEAN NOT NULL DEFAULT FALSE,
  device_api_key        VARCHAR(64),
  updated_at            TIMESTAMPTZ DEFAULT NOW()
);


-- ------------------------------------------------------------
-- GCash payments
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS gcash_payments (
  id          SERIAL PRIMARY KEY,
  ref_code    VARCHAR(30) NOT NULL,
  amount      NUMERIC(6,2) NOT NULL DEFAULT 10.00,
  slot_id     INT REFERENCES slots(id) ON DELETE SET NULL,
  status      TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),
  created_at  TIMESTAMPTZ DEFAULT NOW(),
  resolved_at TIMESTAMPTZ
);


-- ------------------------------------------------------------
-- Notifications
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS notifications (
  id         SERIAL PRIMARY KEY,
  type       TEXT NOT NULL DEFAULT 'system' CHECK (type IN ('gcash','stock','coin_box','tamper','system','sms')),
  level      TEXT NOT NULL DEFAULT 'info' CHECK (level IN ('info','warning','critical')),
  message    VARCHAR(255) NOT NULL,
  is_read    BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ DEFAULT NOW()
);


-- ============================================================
-- Row Level Security & Permissions
-- ============================================================
ALTER TABLE admins              DISABLE ROW LEVEL SECURITY;
ALTER TABLE slots               DISABLE ROW LEVEL SECURITY;
ALTER TABLE transactions        DISABLE ROW LEVEL SECURITY;
ALTER TABLE device_health       DISABLE ROW LEVEL SECURITY;
ALTER TABLE machine_health_logs  DISABLE ROW LEVEL SECURITY;
ALTER TABLE machine_settings    DISABLE ROW LEVEL SECURITY;
ALTER TABLE gcash_payments      DISABLE ROW LEVEL SECURITY;
ALTER TABLE notifications       DISABLE ROW LEVEL SECURITY;

-- Grant access to the API (anon & authenticated roles)
GRANT USAGE ON SCHEMA public TO anon, authenticated;
GRANT ALL ON ALL TABLES IN SCHEMA public TO anon, authenticated;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated;
GRANT ALL ON ALL ROUTINES IN SCHEMA public TO anon, authenticated;

ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO anon, authenticated;



-- ===== 20260910053637_firmware_connection.sql =====

-- ============================================================================
-- 4Peace — Supabase FIX for safe vending transactions
-- Run this ONCE in Supabase SQL Editor before using the fixed firmware.
-- ============================================================================

-- 1) GCash reference must not be re-used.
ALTER TABLE public.gcash_payments
  ADD COLUMN IF NOT EXISTS consumed_at timestamptz NULL;

CREATE UNIQUE INDEX IF NOT EXISTS gcash_payments_ref_code_uq
  ON public.gcash_payments (ref_code);

-- 2) Device transaction ID gives us idempotent replay after Wi-Fi loss/reboot.
ALTER TABLE public.transactions
  ADD COLUMN IF NOT EXISTS device_tx_id text NULL;

ALTER TABLE public.transactions
  ADD COLUMN IF NOT EXISTS machine_id text NULL;

ALTER TABLE public.transactions
  ADD COLUMN IF NOT EXISTS payment_ref_code text NULL;

CREATE UNIQUE INDEX IF NOT EXISTS transactions_device_tx_id_uq
  ON public.transactions (device_tx_id)
  WHERE device_tx_id IS NOT NULL;

-- 3) Atomic vend completion.
--    - validates device API key
--    - prevents duplicate device transaction replay
--    - validates unconsumed approved GCash payment
--    - locks and decrements stock atomically
--    - inserts transaction
--    - consumes GCash payment
CREATE OR REPLACE FUNCTION public.complete_vend(
  p_device_key text,
  p_device_tx_id text,
  p_machine_id text,
  p_ref_code text,
  p_method text,
  p_slot_id bigint,
  p_amount numeric
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $$
DECLARE
  v_expected_key text;
  v_current_stock integer;
  v_new_stock integer;
  v_payment_status text;
  v_consumed_at timestamptz;
  v_payment_amount numeric;
BEGIN
  -- Validate current device key from latest machine settings.
  SELECT device_api_key
    INTO v_expected_key
  FROM public.machine_settings
  ORDER BY id DESC
  LIMIT 1;

  IF v_expected_key IS NULL OR p_device_key IS DISTINCT FROM v_expected_key THEN
    RAISE EXCEPTION 'invalid device key'
      USING ERRCODE = '28000';
  END IF;

  IF p_device_tx_id IS NULL OR length(trim(p_device_tx_id)) < 8 THEN
    RAISE EXCEPTION 'invalid device transaction id';
  END IF;

  IF p_method IS NULL OR p_method NOT IN ('coin', 'gcash') THEN
    RAISE EXCEPTION 'invalid payment method';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 OR p_amount > 9999.99 THEN
    RAISE EXCEPTION 'invalid amount';
  END IF;
  IF p_machine_id IS NULL OR length(trim(p_machine_id)) = 0 THEN
    RAISE EXCEPTION 'invalid machine id';
  END IF;
  -- Serialize duplicate attempts before the existence check.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_device_tx_id, 0));

  -- Idempotency:
  -- if firmware already synced this transaction and retries after losing the ACK,
  -- return success without decrementing stock again.
  IF EXISTS (
    SELECT 1
    FROM public.transactions
    WHERE device_tx_id = p_device_tx_id
  ) THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.transactions
      WHERE device_tx_id = p_device_tx_id AND slot_id = p_slot_id
        AND machine_id = p_machine_id AND method = p_method AND amount = p_amount
        AND payment_ref_code IS NOT DISTINCT FROM NULLIF(p_ref_code, '')
    ) THEN
      RAISE EXCEPTION 'device transaction id reused with different details';
    END IF;
    SELECT stock
      INTO v_current_stock
    FROM public.slots
    WHERE id = p_slot_id;

    RETURN jsonb_build_object(
      'success', true,
      'duplicate', true,
      'stock', v_current_stock
    );
  END IF;

  -- Validate GCash approval before completing a GCash vend.
  IF p_method = 'gcash' THEN
    SELECT status, consumed_at, amount
      INTO v_payment_status, v_consumed_at, v_payment_amount
    FROM public.gcash_payments
    WHERE ref_code = p_ref_code
      AND slot_id = p_slot_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'gcash reference not found';
    END IF;

    IF v_consumed_at IS NOT NULL OR v_payment_status = 'consumed' THEN
      RAISE EXCEPTION 'gcash reference already consumed';
    END IF;

    IF v_payment_amount IS DISTINCT FROM p_amount THEN
      RAISE EXCEPTION 'gcash amount mismatch';
    END IF;

    IF v_payment_status <> 'approved' THEN
      RAISE EXCEPTION 'gcash payment is not approved';
    END IF;
  END IF;

  -- Lock the stock row and verify availability.
  SELECT stock
    INTO v_current_stock
  FROM public.slots
  WHERE id = p_slot_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'slot not found';
  END IF;

  IF v_current_stock <= 0 THEN
    RAISE EXCEPTION 'slot is out of stock';
  END IF;

  UPDATE public.slots
  SET stock = stock - 1,
      updated_at = now()
  WHERE id = p_slot_id
  RETURNING stock INTO v_new_stock;

  INSERT INTO public.transactions (
    ref_code,
    method,
    slot_id,
    amount,
    device_tx_id,
    machine_id,
    payment_ref_code
  )
  VALUES (
    CASE
      WHEN p_method = 'gcash' THEN p_ref_code
      ELSE p_device_tx_id
    END,
    p_method,
    p_slot_id,
    p_amount,
    p_device_tx_id,
    p_machine_id,
    NULLIF(p_ref_code, '')
  );

  IF p_method = 'gcash' THEN
    UPDATE public.gcash_payments
    SET consumed_at = now(),
        resolved_at = COALESCE(resolved_at, now())
    WHERE ref_code = p_ref_code;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'duplicate', false,
    'stock', v_new_stock
  );
END;
$$;

-- Allow the Supabase publishable/anon client to execute this RPC.
-- Security still depends on the device key checked inside the function.
GRANT EXECUTE ON FUNCTION public.complete_vend(
  text, text, text, text, text, bigint, numeric
) TO anon, authenticated;

-- ============================================================================
-- IMPORTANT
-- Set machine_settings.device_api_key to the SAME value as DEVICE_API_KEY in
-- config.h before flashing the ESP32.
-- ============================================================================

-- consumed_at is the fulfillment marker. Keep the existing approved status
-- compatible with the original constraint and older dashboard versions.
CREATE OR REPLACE FUNCTION public.stamp_device_health_sync()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
BEGIN
  NEW.last_sync := now();
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS stamp_device_health_sync ON public.device_health;
CREATE TRIGGER stamp_device_health_sync BEFORE UPDATE ON public.device_health
FOR EACH ROW EXECUTE FUNCTION public.stamp_device_health_sync();
NOTIFY pgrst, 'reload schema';


-- ===== 20260911090000_enable_dashboard_realtime.sql =====

-- Realtime dashboard listeners use these tables.  The block is safe to run more than once.
DO $$
DECLARE
  realtime_table text;
BEGIN
  FOREACH realtime_table IN ARRAY ARRAY[
    'admins',
    'device_health',
    'gcash_payments',
    'machine_health_logs',
    'machine_settings',
    'notifications',
    'slots',
    'transactions'
  ]
  LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime'
        AND schemaname = 'public'
        AND tablename = realtime_table
    ) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', realtime_table);
    END IF;
  END LOOP;
END $$;


-- ===== 20260911100000_sms_outbox.sql =====

-- ============================================================================
-- Durable SIM800L SMS outbox
-- ============================================================================
-- The ESP32 uploads every machine SMS event here before it sends anything via
-- GSM. Rows remain pending after a modem failure, allowing later retry without
-- blocking newer pending rows.

CREATE TABLE IF NOT EXISTS public.sms (
  id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  client_event_id TEXT NOT NULL UNIQUE,
  machine_id      TEXT NOT NULL,
  event_type      TEXT NOT NULL CHECK (
                    event_type IN (
                      'dispensed_product',
                      'payment',
                      'theft_alert',
                      'low_stock'
                    )
                  ),
  recipient       VARCHAR(30) NOT NULL,
  message         VARCHAR(320) NOT NULL,
  status          TEXT NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending', 'sent')),
  attempt_count   INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  last_attempt_at TIMESTAMPTZ,
  last_error      VARCHAR(255),
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  sent_at         TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS sms_pending_queue_idx
  ON public.sms (id)
  WHERE status = 'pending';

-- Server timestamps prevent the ESP32's local clock from affecting delivery
-- history. The ESP32 increases attempt_count only after a modem failure.
CREATE OR REPLACE FUNCTION public.stamp_sms_delivery()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $$
BEGIN
  IF NEW.status = 'sent' AND OLD.status = 'pending' THEN
    NEW.sent_at := now();
    NEW.last_attempt_at := now();
    NEW.last_error := NULL;
  ELSIF NEW.status = 'pending' AND NEW.attempt_count > OLD.attempt_count THEN
    NEW.last_attempt_at := now();
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS stamp_sms_delivery ON public.sms;
CREATE TRIGGER stamp_sms_delivery
BEFORE UPDATE ON public.sms
FOR EACH ROW EXECUTE FUNCTION public.stamp_sms_delivery();

-- Keep permissions consistent with the current firmware tables. The existing
-- project has RLS disabled; a future Auth/RLS rollout should replace this.
ALTER TABLE public.sms DISABLE ROW LEVEL SECURITY;
GRANT ALL ON TABLE public.sms TO anon, authenticated;
GRANT USAGE, SELECT ON SEQUENCE public.sms_id_seq TO anon, authenticated;

-- Optional realtime support lets the dashboard observe the SMS queue.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime'
      AND schemaname = 'public'
      AND tablename = 'sms'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.sms;
  END IF;
END $$;

NOTIFY pgrst, 'reload schema';


-- ===== 20260911110000_device_resource_telemetry.sql =====

-- Historical ESP32 resource telemetry for the Device Health dashboard charts.
CREATE TABLE IF NOT EXISTS public.device_resource_logs (
  id                          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  machine_id                  TEXT NOT NULL,
  internal_sram_total_bytes   BIGINT NOT NULL,
  internal_sram_free_bytes    BIGINT NOT NULL,
  external_psram_total_bytes  BIGINT NOT NULL,
  external_psram_free_bytes   BIGINT NOT NULL,
  external_flash_total_bytes  BIGINT NOT NULL,
  external_flash_used_bytes   BIGINT NOT NULL,
  filesystem_total_bytes      BIGINT NOT NULL,
  filesystem_used_bytes       BIGINT NOT NULL,
  rom_total_bytes             BIGINT NOT NULL,
  cpu_temperature_c           NUMERIC(5,2),
  collected_at                TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS device_resource_logs_collected_at_idx
  ON public.device_resource_logs (collected_at DESC);

ALTER TABLE public.device_resource_logs DISABLE ROW LEVEL SECURITY;
GRANT ALL ON TABLE public.device_resource_logs TO anon, authenticated;
GRANT USAGE, SELECT ON SEQUENCE public.device_resource_logs_id_seq TO anon, authenticated;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime'
      AND schemaname = 'public'
      AND tablename = 'device_resource_logs'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.device_resource_logs;
  END IF;
END $$;

NOTIFY pgrst, 'reload schema';


-- ===== 20260911120000_authenticated_device_telemetry.sql =====

-- Only the ESP32 telemetry RPC may write health/resource records.
REVOKE INSERT, UPDATE, DELETE ON TABLE public.device_health, public.device_resource_logs FROM anon, authenticated;
GRANT SELECT ON TABLE public.device_health, public.device_resource_logs TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.sync_device_telemetry(
  p_device_key text,
  p_machine_id text,
  p_device_health_id integer,
  p_health jsonb,
  p_resource jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  expected_device_key text;
BEGIN
  SELECT device_api_key
  INTO expected_device_key
  FROM machine_settings
  ORDER BY id DESC
  LIMIT 1;

  IF expected_device_key IS NULL OR p_device_key IS DISTINCT FROM expected_device_key THEN
    RETURN jsonb_build_object('success', false, 'message', 'invalid device key');
  END IF;

  IF p_machine_id <> 'VM001' THEN
    RETURN jsonb_build_object('success', false, 'message', 'invalid machine id');
  END IF;

  UPDATE device_health
  SET esp32_uptime_seconds = COALESCE((p_health ->> 'esp32_uptime_seconds')::integer, esp32_uptime_seconds),
      coin_pulses_session = COALESCE((p_health ->> 'coin_pulses_session')::integer, coin_pulses_session),
      coin_box_pulses_total = COALESCE((p_health ->> 'coin_box_pulses_total')::integer, coin_box_pulses_total),
      sim800l_signal_pct = COALESCE((p_health ->> 'sim800l_signal_pct')::integer, sim800l_signal_pct),
      buck1_voltage = COALESCE((p_health ->> 'buck1_voltage')::numeric, buck1_voltage),
      buck2_voltage = COALESCE((p_health ->> 'buck2_voltage')::numeric, buck2_voltage),
      tamper_status = COALESCE(p_health ->> 'tamper_status', tamper_status)
  WHERE id = p_device_health_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'device health record not found');
  END IF;

  INSERT INTO device_resource_logs (
    machine_id, internal_sram_total_bytes, internal_sram_free_bytes,
    external_psram_total_bytes, external_psram_free_bytes,
    external_flash_total_bytes, external_flash_used_bytes,
    filesystem_total_bytes, filesystem_used_bytes, rom_total_bytes,
    cpu_temperature_c
  ) VALUES (
    p_machine_id,
    COALESCE((p_resource ->> 'internal_sram_total_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'internal_sram_free_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'external_psram_total_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'external_psram_free_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'external_flash_total_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'external_flash_used_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'filesystem_total_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'filesystem_used_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'rom_total_bytes')::bigint, 0),
    NULLIF(p_resource ->> 'cpu_temperature_c', '')::numeric
  );

  RETURN jsonb_build_object('success', true);
END;
$$;

GRANT EXECUTE ON FUNCTION public.sync_device_telemetry(text, text, integer, jsonb, jsonb) TO anon, authenticated;
NOTIFY pgrst, 'reload schema';


-- ===== 20260911130000_esp32_pin_connection_detection.sql =====

ALTER TABLE public.machine_settings
  ADD COLUMN IF NOT EXISTS enable_pin_connection_detection BOOLEAN NOT NULL DEFAULT FALSE;

CREATE TABLE IF NOT EXISTS public.esp32_pin_status (
  id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  machine_id        TEXT NOT NULL,
  gpio              INTEGER NOT NULL,
  pin_label         TEXT NOT NULL,
  current_mode      TEXT NOT NULL,
  connection_status TEXT NOT NULL CHECK (connection_status IN ('connected', 'disconnected')),
  realtime_value    TEXT NOT NULL,
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (machine_id, gpio)
);

CREATE INDEX IF NOT EXISTS esp32_pin_status_machine_updated_idx
  ON public.esp32_pin_status (machine_id, updated_at DESC);

ALTER TABLE public.esp32_pin_status DISABLE ROW LEVEL SECURITY;
GRANT SELECT ON TABLE public.esp32_pin_status TO anon, authenticated;
REVOKE INSERT, UPDATE, DELETE ON TABLE public.esp32_pin_status FROM anon, authenticated;
GRANT USAGE, SELECT ON SEQUENCE public.esp32_pin_status_id_seq TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.sync_esp32_pin_status(
  p_device_key text,
  p_machine_id text,
  p_pins jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  expected_device_key text;
  pin jsonb;
BEGIN
  SELECT device_api_key INTO expected_device_key
  FROM machine_settings
  ORDER BY id DESC
  LIMIT 1;

  IF expected_device_key IS NULL OR p_device_key IS DISTINCT FROM expected_device_key THEN
    RETURN jsonb_build_object('success', false, 'message', 'invalid device key');
  END IF;

  IF p_machine_id <> 'VM001' OR jsonb_typeof(p_pins) <> 'array' THEN
    RETURN jsonb_build_object('success', false, 'message', 'invalid pin status payload');
  END IF;

  FOR pin IN SELECT value FROM jsonb_array_elements(p_pins)
  LOOP
    INSERT INTO esp32_pin_status (
      machine_id, gpio, pin_label, current_mode, connection_status, realtime_value, updated_at
    ) VALUES (
      p_machine_id,
      (pin ->> 'gpio')::integer,
      pin ->> 'pin_label',
      pin ->> 'current_mode',
      pin ->> 'connection_status',
      pin ->> 'realtime_value',
      now()
    )
    ON CONFLICT (machine_id, gpio) DO UPDATE SET
      pin_label = EXCLUDED.pin_label,
      current_mode = EXCLUDED.current_mode,
      connection_status = EXCLUDED.connection_status,
      realtime_value = EXCLUDED.realtime_value,
      updated_at = EXCLUDED.updated_at;
  END LOOP;

  RETURN jsonb_build_object('success', true);
END;
$$;

GRANT EXECUTE ON FUNCTION public.sync_esp32_pin_status(text, text, jsonb) TO anon, authenticated;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public'
      AND tablename = 'esp32_pin_status'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.esp32_pin_status;
  END IF;
END $$;

NOTIFY pgrst, 'reload schema';


-- ===== 20260911140000_esp32_pin_devices.sql =====

-- Device catalog and per-PIN assignment for the ESP32 connection inspector.
CREATE TABLE IF NOT EXISTS public.esp32_pin_devices (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL CHECK (char_length(btrim(name)) BETWEEN 1 AND 100),
  image_url TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (name)
);

CREATE TABLE IF NOT EXISTS public.esp32_pin_device_assignments (
  machine_id TEXT NOT NULL,
  gpio INTEGER NOT NULL CHECK (gpio BETWEEN 0 AND 39),
  device_id BIGINT NOT NULL REFERENCES public.esp32_pin_devices(id) ON DELETE CASCADE,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (machine_id, gpio)
);

CREATE INDEX IF NOT EXISTS esp32_pin_device_assignments_device_idx
  ON public.esp32_pin_device_assignments (device_id);

ALTER TABLE public.esp32_pin_devices DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.esp32_pin_device_assignments DISABLE ROW LEVEL SECURITY;

GRANT SELECT ON public.esp32_pin_devices, public.esp32_pin_device_assignments TO anon, authenticated;
REVOKE INSERT, UPDATE, DELETE ON public.esp32_pin_devices, public.esp32_pin_device_assignments FROM anon, authenticated;

CREATE OR REPLACE FUNCTION public.create_esp32_pin_device(
  p_name TEXT,
  p_image_url TEXT DEFAULT ''
)
RETURNS public.esp32_pin_devices
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  created_device public.esp32_pin_devices;
  normalized_name TEXT := btrim(p_name);
  normalized_image_url TEXT := btrim(COALESCE(p_image_url, ''));
BEGIN
  IF char_length(normalized_name) NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'device name must be between 1 and 100 characters';
  END IF;

  IF normalized_image_url <> '' AND normalized_image_url !~* '^https?://.+' THEN
    RAISE EXCEPTION 'image link must start with http:// or https://';
  END IF;

  INSERT INTO public.esp32_pin_devices (name, image_url)
  VALUES (normalized_name, normalized_image_url)
  RETURNING * INTO created_device;

  RETURN created_device;
END;
$$;

CREATE OR REPLACE FUNCTION public.assign_esp32_pin_device(
  p_machine_id TEXT,
  p_gpio INTEGER,
  p_device_id BIGINT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF p_machine_id <> 'VM001' OR p_gpio NOT BETWEEN 0 AND 39 THEN
    RETURN jsonb_build_object('success', false, 'message', 'invalid machine or GPIO');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.esp32_pin_devices WHERE id = p_device_id) THEN
    RETURN jsonb_build_object('success', false, 'message', 'device not found');
  END IF;

  INSERT INTO public.esp32_pin_device_assignments (machine_id, gpio, device_id, updated_at)
  VALUES (p_machine_id, p_gpio, p_device_id, now())
  ON CONFLICT (machine_id, gpio) DO UPDATE
  SET device_id = EXCLUDED.device_id, updated_at = EXCLUDED.updated_at;

  RETURN jsonb_build_object('success', true);
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_esp32_pin_device(TEXT, TEXT) TO anon, authenticated;
GRANT EXECUTE ON FUNCTION public.assign_esp32_pin_device(TEXT, INTEGER, BIGINT) TO anon, authenticated;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public'
      AND tablename = 'esp32_pin_devices'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.esp32_pin_devices;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public'
      AND tablename = 'esp32_pin_device_assignments'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.esp32_pin_device_assignments;
  END IF;
END $$;

NOTIFY pgrst, 'reload schema';


-- ===== 20260912100000_esp32_realtime_heartbeat.sql =====

-- Lightweight ESP32 presence signal for the dashboard's connected/waiting label.
-- The firmware writes this every 10 seconds. It does not create health-history rows.

CREATE TABLE IF NOT EXISTS public.esp32_device_presence (
  machine_id TEXT PRIMARY KEY,
  last_seen  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

GRANT SELECT ON TABLE public.esp32_device_presence TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.heartbeat_esp32(
  p_device_key TEXT,
  p_machine_id TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  expected_device_key TEXT;
BEGIN
  SELECT device_api_key
  INTO expected_device_key
  FROM public.machine_settings
  ORDER BY id DESC
  LIMIT 1;

  IF expected_device_key IS NULL OR p_device_key IS DISTINCT FROM expected_device_key THEN
    RETURN jsonb_build_object('success', false, 'message', 'invalid device key');
  END IF;

  IF p_machine_id <> 'VM001' THEN
    RETURN jsonb_build_object('success', false, 'message', 'invalid machine id');
  END IF;

  INSERT INTO public.esp32_device_presence (machine_id, last_seen)
  VALUES (p_machine_id, NOW())
  ON CONFLICT (machine_id) DO UPDATE SET last_seen = EXCLUDED.last_seen;

  RETURN jsonb_build_object('success', true);
END;
$$;

GRANT EXECUTE ON FUNCTION public.heartbeat_esp32(TEXT, TEXT) TO anon, authenticated;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime'
      AND schemaname = 'public'
      AND tablename = 'esp32_device_presence'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.esp32_device_presence;
  END IF;
END;
$$;

NOTIFY pgrst, 'reload schema';


-- ===== 20260912110000_repair_device_health_telemetry.sql =====

CREATE OR REPLACE FUNCTION public.sync_device_telemetry(
  p_device_key text,
  p_machine_id text,
  p_device_health_id integer,
  p_health jsonb,
  p_resource jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  expected_device_key text;
BEGIN
  SELECT device_api_key
  INTO expected_device_key
  FROM public.machine_settings
  ORDER BY id DESC
  LIMIT 1;

  IF expected_device_key IS NULL OR p_device_key IS DISTINCT FROM expected_device_key THEN
    RETURN jsonb_build_object('success', false, 'message', 'invalid device key');
  END IF;

  IF p_machine_id <> 'VM001' THEN
    RETURN jsonb_build_object('success', false, 'message', 'invalid machine id');
  END IF;

  IF p_device_health_id <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'invalid device health id');
  END IF;

  -- A TRUNCATE or manual cleanup must not permanently disable device telemetry.
  INSERT INTO public.device_health (id)
  VALUES (p_device_health_id)
  ON CONFLICT (id) DO NOTHING;

  UPDATE public.device_health
  SET esp32_uptime_seconds = COALESCE((p_health ->> 'esp32_uptime_seconds')::integer, esp32_uptime_seconds),
      coin_pulses_session = COALESCE((p_health ->> 'coin_pulses_session')::integer, coin_pulses_session),
      coin_box_pulses_total = COALESCE((p_health ->> 'coin_box_pulses_total')::integer, coin_box_pulses_total),
      sim800l_signal_pct = COALESCE((p_health ->> 'sim800l_signal_pct')::integer, sim800l_signal_pct),
      buck1_voltage = COALESCE((p_health ->> 'buck1_voltage')::numeric, buck1_voltage),
      buck2_voltage = COALESCE((p_health ->> 'buck2_voltage')::numeric, buck2_voltage),
      tamper_status = COALESCE(p_health ->> 'tamper_status', tamper_status)
  WHERE id = p_device_health_id;

  INSERT INTO public.device_resource_logs (
    machine_id, internal_sram_total_bytes, internal_sram_free_bytes,
    external_psram_total_bytes, external_psram_free_bytes,
    external_flash_total_bytes, external_flash_used_bytes,
    filesystem_total_bytes, filesystem_used_bytes, rom_total_bytes,
    cpu_temperature_c
  ) VALUES (
    p_machine_id,
    COALESCE((p_resource ->> 'internal_sram_total_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'internal_sram_free_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'external_psram_total_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'external_psram_free_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'external_flash_total_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'external_flash_used_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'filesystem_total_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'filesystem_used_bytes')::bigint, 0),
    COALESCE((p_resource ->> 'rom_total_bytes')::bigint, 0),
    NULLIF(p_resource ->> 'cpu_temperature_c', '')::numeric
  );

  RETURN jsonb_build_object('success', true);
END;
$$;

GRANT EXECUTE ON FUNCTION public.sync_device_telemetry(text, text, integer, jsonb, jsonb) TO anon, authenticated;
NOTIFY pgrst, 'reload schema';


-- ===== 20260915100000_esp32_event_logs.sql =====

-- Server-timestamped ESP32 activity log for the dashboard.
CREATE TABLE IF NOT EXISTS public.esp32_logs (
  id         BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  machine_id TEXT NOT NULL,
  level      TEXT NOT NULL DEFAULT 'info' CHECK (level IN ('info', 'warning', 'error')),
  category   TEXT NOT NULL,
  message    TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS esp32_logs_machine_created_idx
  ON public.esp32_logs (machine_id, created_at DESC);

ALTER TABLE public.esp32_logs DISABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.esp32_logs TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.write_esp32_log(
  p_device_key TEXT,
  p_machine_id TEXT,
  p_level TEXT,
  p_category TEXT,
  p_message TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  expected_device_key TEXT;
BEGIN
  SELECT device_api_key
  INTO expected_device_key
  FROM public.machine_settings
  ORDER BY id DESC
  LIMIT 1;

  IF expected_device_key IS NULL OR p_device_key IS DISTINCT FROM expected_device_key THEN
    RETURN jsonb_build_object('success', false, 'message', 'invalid device key');
  END IF;

  IF p_machine_id <> 'VM001' THEN
    RETURN jsonb_build_object('success', false, 'message', 'invalid machine id');
  END IF;

  IF p_level NOT IN ('info', 'warning', 'error') OR length(trim(p_category)) = 0 OR length(trim(p_message)) = 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'invalid log event');
  END IF;

  INSERT INTO public.esp32_logs (machine_id, level, category, message)
  VALUES (p_machine_id, p_level, left(trim(p_category), 64), left(trim(p_message), 500));

  RETURN jsonb_build_object('success', true);
END;
$$;

GRANT EXECUTE ON FUNCTION public.write_esp32_log(TEXT, TEXT, TEXT, TEXT, TEXT) TO anon, authenticated;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = 'esp32_logs'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.esp32_logs;
  END IF;
END;
$$;

NOTIFY pgrst, 'reload schema';


-- ===== 20260915110000_slot_restock.sql =====

-- Atomically adds physical stock without exceeding the slot capacity.
CREATE OR REPLACE FUNCTION public.restock_slot(
  p_slot_id INTEGER,
  p_quantity INTEGER
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  current_stock INTEGER;
  slot_capacity INTEGER;
  new_stock INTEGER;
BEGIN
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'quantity must be positive');
  END IF;

  SELECT stock, capacity
  INTO current_stock, slot_capacity
  FROM public.slots
  WHERE id = p_slot_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'slot not found');
  END IF;

  IF current_stock >= slot_capacity THEN
    RETURN jsonb_build_object('success', false, 'message', 'slot is already at capacity');
  END IF;

  new_stock := LEAST(slot_capacity, current_stock + p_quantity);

  UPDATE public.slots
  SET stock = new_stock,
      updated_at = NOW()
  WHERE id = p_slot_id;

  RETURN jsonb_build_object('success', true, 'stock', new_stock, 'added', new_stock - current_stock, 'capacity', slot_capacity);
END;
$$;

GRANT EXECUTE ON FUNCTION public.restock_slot(INTEGER, INTEGER) TO anon, authenticated;
NOTIFY pgrst, 'reload schema';


-- ===== 20261103000000_supabase_auth_profiles.sql =====

-- Additive Supabase Auth migration. Legacy password values cannot be imported as Auth passwords.
CREATE TABLE IF NOT EXISTS public.profiles (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  username TEXT NOT NULL UNIQUE CHECK (char_length(btrim(username)) BETWEEN 1 AND 50),
  full_name TEXT NOT NULL DEFAULT '',
  phone TEXT,
  role TEXT NOT NULL DEFAULT 'Administrator' CHECK (role IN ('Administrator', 'Machine Technician')),
  last_login TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "profiles: read own" ON public.profiles;
CREATE POLICY "profiles: read own" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
DROP POLICY IF EXISTS "profiles: update own" ON public.profiles;
CREATE POLICY "profiles: update own" ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());

-- Retain the imported legacy account record for audit only. Dashboard users
-- authenticate through auth.users and profiles, never through password_hash.
ALTER TABLE public.admins ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.admins FROM anon, authenticated;

CREATE OR REPLACE FUNCTION public.create_profile_for_auth_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  INSERT INTO public.profiles (id, username, full_name, phone)
  VALUES (NEW.id, COALESCE(NULLIF(btrim(NEW.raw_user_meta_data ->> 'username'), ''), split_part(NEW.email, '@', 1)), COALESCE(NEW.raw_user_meta_data ->> 'full_name', ''), NULLIF(btrim(NEW.raw_user_meta_data ->> 'phone'), ''))
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS create_profile_for_auth_user ON auth.users;
CREATE TRIGGER create_profile_for_auth_user AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile_for_auth_user();

-- Link pre-existing Auth users only after identity verification:
